// Le nœud Google Calendar est en continueOnFail : un échec OAuth arrive ici sous la
// forme { error: ... }. On sort toujours un item exploitable, meetLink pouvant être null.
const input = $input.first().json;
const interview = $('Préparer données entretien').first().json;

const event = input.error ? {} : input;
const calendarError = input.error ? (input.error.message || String(input.error)) : null;

let meetLink = event.hangoutLink || null;
if (!meetLink && event.conferenceData) {
  const entries = event.conferenceData.entries || [];
  const candidate = entries
    .flatMap(entry => [entry.uri, entry.iconLink])
    .filter(link => typeof link === 'string' && link.startsWith('https://'));
  meetLink = candidate[0] || event.conferenceData.conferenceUri || null;
}

return [{ json: {
  ...interview,
  eventId: event.id || null,
  meetLink,
  calendarError
} }];

// Pas de lien : on ne PATCH pas le backend (un meetLink vide provoquait une 500 et
// épuisait l'outbox). L'événement reste malgré tout notifié par e-mail.
const item = $input.first().json;
return [{ json: {
  interviewId: item.interviewId,
  warning: 'Lien Google Meet indisponible — événement Calendar non créé ou OAuth expiré',
  calendarError: item.calendarError
} }];
